// Podcast feeds carry the audio file in the item's <enclosure> tag.
// The RSS trigger (rss-parser) exposes it as item.enclosure.url.
// Fall back to the item link only if the feed has no enclosure.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const audioUrl = (j.enclosure && j.enclosure.url) || j.link;
  if (!audioUrl) continue; // nothing transcribable in this item
  out.push({
    json: {
      audioUrl,
      episodeTitle: j.title || '',
      publishedAt: j.isoDate || j.pubDate || '',
    },
  });
}
return out;

// The Actor's dataset contains type:'transcript' rows (one per audio file)
// and type:'error' rows for files it could not or did not process
// (error rows are never billed). Keep only the transcripts.
return $input.all().filter((item) => item.json.type === 'transcript');
